import { get_organization_entity } from "@/mixins/GetOrganizationEntity.js";
export default {
  mixins: [get_sub_categories, get_global_categories, get_global_customers, get_organization_entity, get_quotation_list],
  components: {
    ProformaPreview,
    AddQuotationSub,
    EditQuotationSub
  },
  data() {
    return {
      selectCustomer: "",
      customerName: "",
      selectedData: "",
      customerAddress: "",
      selectquotation: "",
      selectEntity: "",
      customerEmailID: "",
      searchF: "",
      searchF1: "",
      searchquotation: "",
      termCondtion: "",
      userArray: [],
      lineItems: "",
      selectCategories: "",
      selectSubCategories: "",
      quotationType: "MASTER",
      customerType: "EXISTING_CUSTOMER",
      itemsData: "",
      quantity: "",
      price: "",
      gstTax: "",
      fixed: true,
      headers: [{
        title: "Category",
        value: "category",
        sortable: false
      }, {
        title: "Item",
        value: "item",
        sortable: false
      }, {
        title: "Price",
        value: "price",
        sortable: false
      }, {
